// RENDER - PRINCIPAL
// ════════════════════════════════════════════════════════════════════

function render(i){
  console.log("[GDI] Render called with path:",i);
  i.indexOf("?")>=0&&(i=i.substr(0,i.indexOf("?")));
  title(i);
  nav(i);
  const e=/\/\d+:$/g;
  if(i.includes("/fallback")){
    window.scroll_status={event_bound:!1,loading_lock:!1};
    const t=getQueryVariable("a"),n=decodeURIComponent(getQueryVariable("id")||"");
    return t?fallback(n,!0):list(null,n,!0);
  }else if(window.MODEL?.is_search_page){
    window.scroll_status={event_bound:!1,loading_lock:!1};
    render_search_result_list();
  }else if(i.match(e)||i.slice(-1)=="/"){
    window.scroll_status={event_bound:!1,loading_lock:!1};
    list(i);
  }else{
    file(i);
  }
}

