function list(i,e="",t=!1){
  console.log("[GDI] List view for:",i);
  const n=window.location.pathname,a=trimChar(n,"/").split("/");
  let c="/",l='<li><a href="/">Home</a></li><li class="gdi-bc-sep">/</li>';
  if(a.length>1)for(const p in a){const g=a[p];let f;try{f=decodeURIComponent(g)}catch{f=g}f=f.replace(/\//g,"%2F");const u=f.match(/^(\d+):$/),h=u&&window.drive_names&&window.drive_names[+u[1]]||f,m=h.length>18?h.slice(0,14)+"…":h;if(c+=g+"/",!m)break;Number(p)===a.length-1?l+=`<li class="gdi-bc-cur" title="${escHtml(h)}">${escHtml(m)}</li>`:l+=`<li><a href="${c}" title="${escHtml(h)}">${escHtml(m)}</a></li><li class="gdi-bc-sep">/</li>`}
  const d=`
<div class="gdi-wrap">
  <div id="update"></div>
  <div id="head_md" class="gdi-panel gdi-markdown" style="display:none;"></div>
  <div id="select_items" class="gdi-select-bar" style="display:none;">
    <label style="display:flex;align-items:center;gap:6px;cursor:pointer;">
      <input type="checkbox" id="select-all-checkboxes"> Select all
    </label>
    <button id="handle-multiple-items-copy" class="gdi-btn gdi-btn-ghost">
      <i class="bi bi-clipboard"></i> Copy selected
    </button>
  </div>
  <div class="gdi-breadcrumb-wrap">
    <ol class="gdi-bc" id="folderne">${l}</ol>
  </div>
  <div class="gdi-panel">
    <div class="gdi-toolbar">
      <input id="folder-filter" class="gdi-filter-input" type="search" placeholder="Filter files…" autocomplete="off">
    </div>
    <div class="gdi-list-header" id="list-header">
      <span class="gdi-col-name gdi-sort-header" data-sort="name">Name</span>
      <span class="gdi-col-size gdi-sort-header" data-sort="size">Size</span>
      <span class="gdi-col-date gdi-sort-header" data-sort="date">Modified</span>
      <span class="gdi-col-acts"></span>
    </div>
    <div id="list"></div>
    <div id="count" class="gdi-count-bar"></div>
  </div>
  <div id="readme_md" class="gdi-panel gdi-markdown" style="display:none;"></div>
</div>`;
  $("#content").html(d);
  const o=localStorage.getItem("password"+i);
  $("#list").html('<div class="gdi-spinner-wrap" id="spinner"><div class="gdi-spinner"></div></div>');
  $("#readme_md").hide().html("");
  $("#head_md").hide().html("");
  
  function s(p,g,f){
    $("#list").data("nextPageToken",p.nextPageToken).data("curPageIndex",p.curPageIndex);
    $("#spinner").remove();
    if(p.nextPageToken===null){
      $(window).off("scroll");
      window.scroll_status.event_bound=!1;
      window.scroll_status.loading_lock=!1;
      t?append_files_to_fallback_list(g,p.data.files):append_files_to_list(g,p.data.files);
    }else{
      t?append_files_to_fallback_list(g,p.data.files):append_files_to_list(g,p.data.files);
      if(window.scroll_status.event_bound!==!0){
        $(window).on("scroll",function(){
          if($(this).scrollTop()+$(this).height()>getDocumentHeight()-(Os.isMobile?130:80)){
            if(window.scroll_status.loading_lock===!0)return;
            window.scroll_status.loading_lock=!0;
            $('<div id="spinner" class="gdi-spinner-wrap"><div class="gdi-spinner"></div></div>').insertBefore("#readme_md");
            const u=$("#list");
            t?requestListPath(g,{id:e,password:f.password,page_token:u.data("nextPageToken"),page_index:u.data("curPageIndex")+1},s,null,5,!0):requestListPath(g,{password:f.password,page_token:u.data("nextPageToken"),page_index:u.data("curPageIndex")+1},s,null);
          }
        });
        window.scroll_status.event_bound=!0;
      }
      if(window.scroll_status.loading_lock===!0){window.scroll_status.loading_lock=!1;}
    }
  }
  
  t?requestListPath(i,{id:e,password:o},s,null,3,!0):requestListPath(i,{password:o},s,null);
  const r=document.getElementById("handle-multiple-items-copy");
  r&&r.addEventListener("click",()=>{
    const p=document.querySelectorAll("input.gdi-row-check:checked");
    if(!p.length){alert("No items selected!");return;}
    const g=Array.from(p).map(f=>f.value).join("\n");
    navigator.clipboard.writeText(g).catch(()=>{const f=document.createElement("textarea");f.value=g;document.body.appendChild(f);f.select();document.execCommand("copy");document.body.removeChild(f);});
    showToast(`${p.length} link${p.length>1?"s":""} copied`);
  });
}

function append_files_to_list(i,e){
  const UI=window.UI||{},t=$("#list"),n=t.data("nextPageToken")===null,a=t.data("curPageIndex")=="0";
  let c="",l=0,d=!1;
  for(const o in e){
    const s=e[o],r=encodeURIComponent(s.name).replace(/\//g,"%2F")+"/",p=i+r.replace(/#/g,"%23").replace(/\?/g,"%3F");
    if(s.modifiedTime=utc2delhi(s.modifiedTime),s.mimeType=="application/vnd.google-apps.folder")c+=`<a href="${p}" class="gdi-row countitems" data-name="${escHtml(s.name.toLowerCase())}" data-date="${s.modifiedTime||""}">
  <span class="gdi-row-icon"><i class="bi bi-folder-fill gdi-icon-folder"></i></span>
  <span class="gdi-row-name">${escHtml(s.name)}</span>
  <span class="gdi-row-size"></span>
  <span class="gdi-row-date">${UI.display_time?s.modifiedTime:""}</span>
  <span class="gdi-row-acts"></span>
</a>`;
    else{
      const g=Number(s.size);
      l+=g;
      s.size=formatFileSize(s.size);
      d=!0;
      const f=s.fileExtension,u=UI.second_domain_for_dl?UI.downloaddomain+s.link:window.location.origin+s.link,h=encodeURIComponent(s.name);
      let m=i+h+"?a=view";
      const v=i+h;
      n&&s.name=="README.md"&&UI.render_readme_md&&get_file(v,s,function(b){markdown("#readme_md",b);$("img").addClass("img-fluid");});
      s.name=="HEAD.md"&&UI.render_head_md&&get_file(v,s,function(b){markdown("#head_md",b);$("img").addClass("img-fluid");});
      const w=GDOC_TYPES[s.mimeType],y=w?w.icon:getFileIcon(f),_=w&&UI.display_download?w.formats.map(b=>`<a class="gdi-act-btn" href="${u}&fmt=${b.ext}" title="Export as ${b.label}" download><span style="font-size:10px;font-weight:600;">${b.label}</span></a>`).join(""):"";
      c+=`<div class="gdi-row countitems size_items" data-name="${escHtml(s.name.toLowerCase())}" data-bytes="${g}" data-date="${s.modifiedTime||""}">
  ${UI.allow_selecting_files?`<input class="gdi-row-check" type="checkbox" value="${u}">`:""}
  <span class="gdi-row-icon">${y}</span>
  <a class="gdi-row-name" href="${m}" title="${escHtml(s.name)}" data-size="${UI.display_size?s.size:""}">${escHtml(s.name)}</a>
  <span class="gdi-row-size">${UI.display_size?s.size:""}</span>
  <span class="gdi-row-date">${UI.display_time?s.modifiedTime:""}</span>
  <span class="gdi-row-acts">
    ${UI.allow_selecting_files?`<button class="gdi-act-btn" onclick="copyShareUrl(this.closest('.gdi-row').querySelector('.gdi-row-name').href)" title="Copy link"><i class="bi bi-link-45deg"></i></button>`:""}
    ${w?_:UI.display_download?`<a class="gdi-act-btn" href="${u}" title="Download"><i class="bi bi-download"></i></a>`:""}
  </span>
</div>`;
    }
  }
  if(d&&UI.allow_selecting_files){document.getElementById("select_items").style.display="flex";}
  t.html((t.data("curPageIndex")=="0"?"":t.html())+c);
  initFolderFilter();
  initColumnSort();
  if(n){
    const o=formatFileSize(l)||"0 Bytes",s=t.find(".countitems").length,r=t.find(".size_items").length,p=s===0?"Empty folder":`${s} item${s===1?"":"s"}`,g=r>0?` · ${r} file${r===1?"":"s"}, ${o}`:"";
    $("#count").addClass("show").html(p+g);
  }
}

function append_files_to_fallback_list(i,e){
  const UI=window.UI||{};
  try{
    const t=$("#list"),n=t.data("nextPageToken")===null;
    let a="",c=0,l=!1;
    for(const d in e){
      const o=e[d],s="/fallback?id="+encodeURIComponent(o.id);
      if(o.modifiedTime=utc2delhi(o.modifiedTime),o.mimeType=="application/vnd.google-apps.folder")a+=`<a href="${s}" class="gdi-row countitems" data-name="${escHtml(o.name.toLowerCase())}" data-date="${o.modifiedTime||""}">
  <span class="gdi-row-icon"><i class="bi bi-folder-fill gdi-icon-folder"></i></span>
  <span class="gdi-row-name">${escHtml(o.name)}</span>
  <span class="gdi-row-size"></span>
  <span class="gdi-row-date">${UI.display_time?o.modifiedTime:""}</span>
  <span class="gdi-row-acts"></span>
</a>`;
      else{
        const r=Number(o.size);
        c+=r;
        o.size=formatFileSize(o.size);
        l=!0;
        const p=o.fileExtension,g=UI.second_domain_for_dl?UI.downloaddomain+o.link:window.location.origin+o.link,f=s+"&a=view";
        a+=`<div class="gdi-row countitems size_items" data-name="${escHtml(o.name.toLowerCase())}" data-bytes="${r}" data-date="${o.modifiedTime||""}">
  ${UI.allow_selecting_files?`<input class="gdi-row-check" type="checkbox" value="${g}">`:""}
  <span class="gdi-row-icon">${getFileIcon(p)}</span>
  <a class="gdi-row-name" href="${f}" title="${escHtml(o.name)}" data-size="${UI.display_size?o.size:""}">${escHtml(o.name)}</a>
  <span class="gdi-row-size">${UI.display_size?o.size:""}</span>
  <span class="gdi-row-date">${UI.display_time?o.modifiedTime:""}</span>
  <span class="gdi-row-acts">
    ${UI.display_download?`<a class="gdi-act-btn" href="${g}" title="Download"><i class="bi bi-download"></i></a>`:""}
  </span>
</div>`;
      }
    }
    if(l&&UI.allow_selecting_files){document.getElementById("select_items").style.display="flex";}
    t.html((t.data("curPageIndex")=="0"?"":t.html())+a);
    if(n){
      const d=formatFileSize(c)||"0 Bytes",o=t.find(".countitems").length,s=t.find(".size_items").length,r=o===0?"Empty folder":`${o} item${o===1?"":"s"}`,p=s>0?` · ${s} file${s===1?"":"s"}, ${d}`:"";
      $("#count").addClass("show").html(r+p);
    }
  }catch(t){console.error(t);}
}

let _folderFilterBound=!1;
function initFolderFilter(){
  const i=document.getElementById("folder-filter");
  if(!i||_folderFilterBound)return;
  _folderFilterBound=!0;
  i.addEventListener("input",function(){
    const e=this.value.toLowerCase();
    document.querySelectorAll("#list .gdi-row").forEach(t=>{
      const n=(t.dataset.name||t.textContent).toLowerCase();
      t.style.display=!e||n.includes(e)?"":"none";
    });
  });
}

let _sortState={col:null,dir:1};
function initColumnSort(){
  const i=document.querySelectorAll("#list-header .gdi-sort-header");
  i.forEach(e=>{
    e.addEventListener("click",function(){
      const t=this.dataset.sort;
      _sortState.col===t?_sortState.dir*=-1:(_sortState.col=t,_sortState.dir=1);
      i.forEach(n=>n.classList.remove("asc","desc"));
      this.classList.add(_sortState.dir===1?"asc":"desc");
      sessionStorage.setItem("gdi-sort",JSON.stringify(_sortState));
      sortFileList(t,_sortState.dir);
    });
  });
  try{const e=JSON.parse(sessionStorage.getItem("gdi-sort"));e&&e.col&&(_sortState=e);}catch{}
}

function sortFileList(i,e){
  const t=$("#list"),n=t.children(".gdi-row").toArray();
  n.sort((a,c)=>{
    if(i==="size")return e*((parseFloat($(a).data("bytes"))||0)-(parseFloat($(c).data("bytes"))||0));
    if(i==="date")return e*(new Date($(a).data("date"))-new Date($(c).data("date")));
    const l=($(a).data("name")||"").toLowerCase(),d=($(c).data("name")||"").toLowerCase();
    return e*l.localeCompare(d);
  });
  n.forEach(a=>t.append(a));
}

function askPassword(i){
  $("#spinner").remove();
  const e=prompt("This folder is password protected. Enter the password:","");
  if(e!=null&&e!=""){localStorage.setItem("password"+i,e);list(i);}else history.go(-1);
}

// ════════════════════════════════════════════════════════════════════
// FILE VIEWER
// ════════════════════════════════════════════════════════════════════

async function file(i){
  console.log("[GDI] File view for:",i);
  const e=getCookie("root_id")||"";
  $("#content").html('<div class="gdi-wrap"><div class="gdi-spinner-wrap" style="height:150px;" id="spinner"><div class="gdi-spinner"></div></div></div>');
  try{
    const t=await fetch("",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({path:i})});
    if(!t.ok)throw new Error("Request failed");
    const n=await t.json();
    dispatchFileView(n,e);
  }catch(t){$("#content").html(renderErrorCard(t));}
}

function dispatchFileView(i,e){
  console.log("[GDI] Dispatch file view:",i.name);
  const UI=window.UI||{},t=i.mimeType,n=i.fileExtension;
  if(t==="application/vnd.google-apps.folder"){window.location.href=window.location.pathname+"/";return;}
  if(!n&&!t)return;
  const a=i.name,c=encodeURIComponent(a),l=formatFileSize(i.size),d=UI.second_domain_for_dl?UI.downloaddomain+i.link:window.location.origin+i.link;
  if(GDOC_TYPES[t])file_workspace(a,l,t,d);
  else if(FILE_TYPES.video.includes(n)||t&&t.includes("video")){const o=i.thumbnailLink?i.thumbnailLink.replace("s220","s0"):UI.poster;file_video(a,c,l,o,d,t,i.id,e,i.subtitles||[]);}
  else if(FILE_TYPES.audio.includes(n)||t&&t.includes("audio"))file_audio(a,c,l,d,i.id,e);
  else if(FILE_TYPES.image.includes(n)||t&&t.includes("image"))file_image(a,c,l,d);
  else if(n==="pdf"||t&&t.includes("pdf"))file_pdf(a,c,l,d,i.id,e);
  else if(FILE_TYPES.code.includes(n))file_code(a,c,l,i.size,d,n,i.id,e);
  else file_others(a,c,l,d);
}

