function copyShareUrl(i){
  navigator.clipboard.writeText(i).then(()=>showToast("Link copied!")).catch(()=>{const e=document.createElement("textarea");e.value=i;document.body.appendChild(e);e.select();document.execCommand("copy");document.body.removeChild(e);showToast("Link copied!");});
}

function showToast(i){
  let e=document.getElementById("gdi-toast-container");
  if(!e){e=document.createElement("div");e.id="gdi-toast-container";document.body.appendChild(e);}
  const t=document.createElement("div");
  t.className="gdi-toast";
  t.innerHTML=`<i class="bi bi-check-circle-fill"></i> ${i}`;
  e.appendChild(t);
  setTimeout(()=>{t.classList.add("gdi-toast-out");setTimeout(()=>t.remove(),200);},2400);
}

function get_file(i,e,t){
  const n="file_path_"+i+e.modifiedTime,a=localStorage.getItem(n);
  if(null!=a)return t(a);
  $.get(i,function(e){localStorage.setItem(n,e);t(e);});
}

function markdown(i,e){
  if(void 0===window.marked){
    const t=document.createElement("script");
    t.src="https://cdn.jsdelivr.net/npm/marked/marked.min.js";
    t.onload=()=>{const n=marked.parse(e);$(i).show().html(n);$("img").addClass("img-fluid");};
    document.head.appendChild(t);
  }else{const t=marked.parse(e);$(i).show().html(t);$("img").addClass("img-fluid");}
}

async function fallback(i,e){
  if(e){
    try{
      const t=await fetch("/0:fallback",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:i})});
      const n=await t.json();
      dispatchFileView(n,"");
    }catch(t){$("#content").html(renderErrorCard(t));}
  }else list(i,!0);
}

function formatFileSize(i){
  const e=Number(i);
  if(isNaN(e)||e<0)return "";
  if(e>=1099511627776)return(e/1099511627776).toFixed(2)+" TB";
  if(e>=1073741824)return(e/1073741824).toFixed(2)+" GB";
  if(e>=1048576)return(e/1048576).toFixed(2)+" MB";
  if(e>=1024)return(e/1024).toFixed(2)+" KB";
  if(e>1)return e+" bytes";
  if(1===e)return"1 byte";
  return"0 bytes";
}

function utc2delhi(i){return i?new Date(i).toLocaleString():"";}

function getCookie(i){
  const e=i+"=",t=document.cookie.split(";");
  for(let n=0;n<t.length;n++){let a=t[n];for(;" "==a.charAt(0);)a=a.substring(1);if(0==a.indexOf(e))return a.substring(e.length);}
  return null;
}

