window.addEventListener("beforeunload",()=>{
  if(window.GDI_ABORT){window.GDI_ABORT.forEach(i=>{try{i.abort();}catch(i){}});window.GDI_ABORT.clear();}
});

window.onpopstate=function(){
  if(window.GDI_ABORT){window.GDI_ABORT.forEach(i=>{try{i.abort();}catch(i){}});window.GDI_ABORT.clear();}
  render(window.location.pathname);
};

document.addEventListener("change",function(i){
  if(i.target&&"select-all-checkboxes"===i.target.id){document.querySelectorAll("input.gdi-row-check").forEach(e=>{e.checked=i.target.checked;});}
});

$(function(){
  console.log("[GDI] Boot sequence started");
  GDIUserSystem.loadUserData();
  init();
  window.UI?.debug_mode&&"undefined"!=typeof GDIDebug&&GDIDebug.attach();
  window.UI?.show_quota&&fetchQuota();
  const i=new URLSearchParams(window.location.search).get("embed");
  "1"===i&&document.body.classList.add("embed-mode");
  console.log("[GDI] Rendering path:",window.location.pathname);
  render(window.location.pathname);
  setTimeout(()=>{
    if(window.location.pathname==="/"||window.location.pathname.match(/\/\d+:\/$/)){
      showContinueWatchingBanner();
    }
  },1e3);
  console.log("[GDI] Boot complete ✓");
});

function fetchQuota(){
  const i=window.current_drive_order||0;
  fetch(`/${i}:quota`).then(i=>i.json()).then(i=>{
    const e=i.storageQuota;
    if(!e)return;
    const t=Number(e.usage||0),n=Number(e.limit||0),a=n>0?Math.min(100,t/n*100):0,c=a>90?"#f44336":a>70?"#ff9800":"#4caf50",l=document.getElementById("gdi-quota-bar"),d=document.getElementById("gdi-quota-text"),o=document.getElementById("gdi-quota-fill");
    l&&d&&o&&(d.textContent=n>0?`${formatFileSize(t)} of ${formatFileSize(n)} (${a.toFixed(1)}%)`:formatFileSize(t),o.style.width=a+"%",o.style.background=c,l.style.display="block");
  }).catch(()=>{});
}

